// swift-tools-version: 6.2
import Foundation
import PackageDescription

// The Rust core is built as a static library by scripts/build-core.sh and copied here.
let rustLibDir = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("lib").path

let package = Package(
    name: "Miiting",
    platforms: [.macOS(.v26)],
    products: [.executable(name: "Miiting", targets: ["Miiting"])],
    targets: [
        // C header + modulemap generated by UniFFI.
        .systemLibrary(name: "miiting_ffiFFI", path: "Sources/miiting_ffiFFI"),
        // Swift bindings generated by UniFFI (do not edit).
        .target(
            name: "MiitingCore",
            dependencies: ["miiting_ffiFFI"],
            path: "Sources/MiitingCore",
            swiftSettings: [.swiftLanguageMode(.v5)],
            linkerSettings: [
                .unsafeFlags(["-L\(rustLibDir)"]),
                .linkedLibrary("miiting_ffi"),
                .linkedLibrary("c++"),
                .linkedFramework("Accelerate"),
                .linkedFramework("Metal"),
                .linkedFramework("MetalKit"),
                .linkedFramework("Foundation"),
                .linkedFramework("CoreFoundation"),
                .linkedFramework("Security"),
                .linkedFramework("SystemConfiguration"),
            ]
        ),
        .executableTarget(
            name: "Miiting",
            dependencies: ["MiitingCore"],
            path: "Sources/Miiting"
        ),
    ]
)
